def histogram(test):
    if not test:
        return {}

    letters = test.split()
    letter_count = {letter: letters.count(letter) for letter in set(letters)}
    max_count = max(letter_count.values())
    result = {letter: count for letter, count in letter_count.items() if count == max_count}
    return result
